import{_ as i}from"./chunks/gruppenprozesse-zk-g-ps.q5zPLHrG.js";import{_ as a,o as t,c as u,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/sekundarstufen/gruppenprozesse-zk-aktivieren.png",b=JSON.parse('{"title":"Die ZP10-Gruppenprozesse im Ablauf verwenden","description":"","frontmatter":{"title":"Die ZP10-Gruppenprozesse im Ablauf verwenden","source_pageid":1158,"source_revision":3896},"headers":[],"relativePath":"zeugnisse/sekundarstufen/zentrale-pruefung-jahrgang-10-gruppenprozesse-zp-10-zk.md","filePath":"zeugnisse/sekundarstufen/zentrale-pruefung-jahrgang-10-gruppenprozesse-zp-10-zk.md"}'),d={name:"zeugnisse/sekundarstufen/zentrale-pruefung-jahrgang-10-gruppenprozesse-zp-10-zk.md"};function o(p,r,g,h,c,f){return t(),u("div",null,[...r[0]||(r[0]=[s('<h1 id="die-zp10-gruppenprozesse-im-ablauf-verwenden" tabindex="-1">Die ZP10-Gruppenprozesse im Ablauf verwenden <a class="header-anchor" href="#die-zp10-gruppenprozesse-im-ablauf-verwenden" aria-label="Permalink to &quot;Die ZP10-Gruppenprozesse im Ablauf verwenden&quot;">​</a></h1><p>Wählen Sie die passende Prüfungsgruppe im zweiten Halbjahr. Die Übersicht führt in der Reihenfolge der Bearbeitung durch die Gruppenprozesse zur Zentralen Prüfung.</p><p><a href="/bilder/sekundarstufen/gruppenprozesse-zk-aktivieren.png"><img src="'+l+'" alt="Die Schaltfläche, um die ZP 10 zu verarbeiten steht zur Verfügung, wenn der Jahrgang 10 exklusiv ausgewählt wurde und im Halbjahr die ZP 10 anliegt." loading="lazy"></a></p><p><em>Die Schaltfläche, um die ZP 10 zu verarbeiten steht zur Verfügung, wenn der Jahrgang 10 exklusiv ausgewählt wurde und im Halbjahr die ZP 10 anliegt.</em></p><p>Diese Gruppenprozesse stehen zur Verfügung, wenn sich zum einen die Schule im <em>2. Halbjahr</em> befindet und weiterhin <em>exklusiv</em> Schüler eines Jahrgangs ausgewählt wurden, in denen Zentrale Klausuren geschrieben werden.</p>',5),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Der Ablauf einer ZP 10 wird im Artikel zum Reiter "),e("em",null,"Schüler ➜ ZP 10/ZK"),n(" detailliert erläutert.")]),e("p",null,[n("Die notwendigen Vorbereitungen, um die ZP 10/Zentrale Klausuren in SchILD-NRW zu erfassen, finden sich in einem "),e("em",null,"Tutorial"),n(".")])],-1),s('<p><a href="/bilder/schueler/gruppenprozesse-zk-g-ps.png"><img src="'+i+'" alt="Die Gruppenprozesse bilden von oben nach unten den Verlauf der Prüfungen/Klausuren ab." loading="lazy"></a></p><p><em>Die Gruppenprozesse bilden von oben nach unten den Verlauf der Prüfungen/Klausuren ab.</em></p><p>Folgende Gruppenprozesse stehen zur Verfügung. Diese bilden von oben nach unten den im Arbeitsablauf der Prüfungen/Klausuren ab und werden entsprechend aufeinanderfolgend ausgeführt.</p><ul><li><strong>Leistungsdaten holen</strong>: Die unter <em>Unterrichtsfächer</em> als für die zentrale Prüfungen/Klausuren zuvor markierten Fächer werden von dem aktuellen Abschnitt (Akt. Halbjahr) geholt.</li><li><strong>Prüfungsnoten aus Teilleistungen holen</strong>: Es sind vorher <em>Teilleistungen</em> zu konfigurieren, in die dann die Noten eingetragen werden. Diese werden über den Gruppenprozess hier geholt. Alle für die ZP10 relevanten Noten sind zwangsläufig vorher einzutragen.</li><li><strong>Mündliche Prüfungen festlegen</strong>: Für das Verfahren seit 1. August 2026 beachten Sie <a href="/zeugnisse/zp10-rechtsstand.html">Notenbildung und mündliche Prüfung</a>. Prüfen Sie automatisch gesetzte Markierungen anhand der aktuellen Regelung. Erfassen Sie die angemeldeten Prüfungen und anschließend deren Ergebnisse.</li><li><strong>Abschlussnoten berechnen</strong>: Sofern die Notenbildung eindeutig ist, kann SchILD-NRW diese als Abschlussnote eintragen. Steht ein Schüler zwischen zwei Notenstufen, ist die Eintragung Hand vorzunehmen.</li><li><strong>Abschlussnoten in Leistungsdaten übertragen</strong>: Schreibt nach Abschluss der Notenfindung diese als die Note in das aktuelle Halbjahr zurück.</li></ul><p>Nach dem Abschluss des ZP-10-Prozesses sind die Notenmitteilungen zu drucken. Um dies mit SchILD-NRW durchzuführen, stehen Formulare auf der Seite des <a href="https://www.svws.nrw.de" target="_blank" rel="noreferrer">MSB zu Schulverwaltungssoftware</a> unter der Rubrik Downloads ➜ SchILD-Reports bei den Einzelreports ➜ Sekundarstufe1 ➜ ZP10 zum Download zur Verfügung.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zentrale_Pr%C3%BCfung_Jahrgang_10_(Gruppenprozesse_ZP_10/ZK)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3896.</p>',7)])])}const _=a(d,[["render",o]]);export{b as __pageData,_ as default};
